process::WFP Seed Pay Rates.PrologProcedure:
#Region Seed Pay Rates — grade/location base x job-family pay index. rev D order: Period, Version, Grade, Job Family, Location, Measure
cCube = 'WFP Pay Rates';
cPer  = 'WFP Period';
nPcount = DIMSIZ( cPer );
nFcount = DIMSIZ( 'WFP Job Family' );

vBase =
'London;G1;28000;32000;36000;2400~' |
'London;G2;42000;50000;58000;2400~' |
'London;G3;66000;80000;94000;2400~' |
'London;G4;100000;120000;140000;3600~' |
'London;G5;160000;195000;235000;4800~' |
'New York;G1;40000;46000;52000;6000~' |
'New York;G2;60000;72000;84000;6000~' |
'New York;G3;100000;122000;145000;6000~' |
'New York;G4;150000;180000;215000;9000~' |
'New York;G5;230000;285000;345000;12000~' |
'Auckland;G1;55000;62000;70000;3000~' |
'Auckland;G2;82000;95000;110000;3000~' |
'Auckland;G3;120000;140000;165000;3000~' |
'Auckland;G4;180000;210000;250000;4500~' |
'Auckland;G5;270000;320000;390000;6000~';

WHILE( SCAN( '~', vBase ) > 1 );
   nS = SCAN( '~', vBase );
   vRec = SUBST( vBase, 1, nS - 1 ) | ';';
   vBase = SUBST( vBase, nS + 1, LONG( vBase ) - nS );

   nS = SCAN(';',vRec); vLoc = SUBST(vRec,1,nS-1); vRec = SUBST(vRec,nS+1,LONG(vRec)-nS);
   nS = SCAN(';',vRec); vGr  = SUBST(vRec,1,nS-1); vRec = SUBST(vRec,nS+1,LONG(vRec)-nS);
   nS = SCAN(';',vRec); nMin = NUMBR(SUBST(vRec,1,nS-1)); vRec = SUBST(vRec,nS+1,LONG(vRec)-nS);
   nS = SCAN(';',vRec); nMid = NUMBR(SUBST(vRec,1,nS-1)); vRec = SUBST(vRec,nS+1,LONG(vRec)-nS);
   nS = SCAN(';',vRec); nMax = NUMBR(SUBST(vRec,1,nS-1)); vRec = SUBST(vRec,nS+1,LONG(vRec)-nS);
   nS = SCAN(';',vRec); nBen = NUMBR(SUBST(vRec,1,nS-1));

   nPen  = IF( vLoc @= 'London', 0.05, IF( vLoc @= 'New York', 0.06, 0.03 ) );
   nEPen = IF( vLoc @= 'London', 0.05, IF( vLoc @= 'New York', 0.06, 0.03 ) );

   nF = 1;
   WHILE( nF <= nFcount );
      vFam = DIMNM( 'WFP Job Family', nF );
      nIdx = ATTRN( 'WFP Job Family', vFam, 'Pay Index' );

      nP = 1;
      WHILE( nP <= nPcount );
         vPer = DIMNM( cPer, nP );
         IF( DTYPE( cPer, vPer ) @= 'N' );
            vVl = 'Budget|Working|';
            WHILE( SCAN( '|', vVl ) > 1 );
               nS = SCAN( '|', vVl );
               vVer = SUBST( vVl, 1, nS - 1 );
               vVl = SUBST( vVl, nS + 1, LONG( vVl ) - nS );

               CellPutN( nMin * nIdx, cCube, vPer, vVer, vGr, vFam, vLoc, 'Salary Min' );
               CellPutN( nMid * nIdx, cCube, vPer, vVer, vGr, vFam, vLoc, 'Salary Mid' );
               CellPutN( nMax * nIdx, cCube, vPer, vVer, vGr, vFam, vLoc, 'Salary Max' );
               CellPutN( nPen,  cCube, vPer, vVer, vGr, vFam, vLoc, 'Pension Pct' );
               CellPutN( nEPen, cCube, vPer, vVer, vGr, vFam, vLoc, 'Employee Pension Pct' );
               CellPutN( nBen,  cCube, vPer, vVer, vGr, vFam, vLoc, 'Benefits Annual' );
            END;
         ENDIF;
         nP = nP + 1;
      END;
      nF = nF + 1;
   END;
END;

process::WFP Seed Workforce Input.PrologProcedure:
#Region Seed Workforce Input — FTE + Base Salary per active month (rev D dim order: Period, Version, Position, Measure)
cCube = 'WFP Workforce Input';
cPos  = 'WFP Position';
cPer  = 'WFP Period';

nPosCount = DIMSIZ( cPos );
nPerCount = DIMSIZ( cPer );

nI = 1;
WHILE( nI <= nPosCount );
   vPos = DIMNM( cPos, nI );
   IF( DTYPE( cPos, vPos ) @= 'N' );
      nFTE = ATTRN( cPos, vPos, 'FTE' );
      nSal = ATTRN( cPos, vPos, 'Seed Base Salary' );
      vStartPd = ATTRS( cPos, vPos, 'Start Period' );
      vEndPd = ATTRS( cPos, vPos, 'End Period' );
      nStartIdx = ATTRN( cPer, vStartPd, 'Period Index' );
      nEndIdx = IF( vEndPd @= '', 999, ATTRN( cPer, vEndPd, 'Period Index' ) );

      nP = 1;
      WHILE( nP <= nPerCount );
         vPer = DIMNM( cPer, nP );
         IF( DTYPE( cPer, vPer ) @= 'N' );
            nPidx = ATTRN( cPer, vPer, 'Period Index' );
            IF( nPidx >= nStartIdx & nPidx <= nEndIdx );
               CellPutN( nFTE, cCube, vPer, 'Budget',   vPos, 'FTE' );
               CellPutN( nSal, cCube, vPer, 'Budget',   vPos, 'Base Salary' );
               CellPutN( nFTE, cCube, vPer, 'Working',  vPos, 'FTE' );
               CellPutN( nSal, cCube, vPer, 'Working',  vPos, 'Base Salary' );
            ENDIF;
         ENDIF;
         nP = nP + 1;
      END;
   ENDIF;
   nI = nI + 1;
END;

