process::WFP Seed FX Rates.PrologProcedure:
#Region Seed FX rates — 1 unit of currency in the reporting currency (GBP). rev D order: Period, Version, Currency, FX Rate Type, Measure
cCube = 'WFP FX Rates';
cPer  = 'WFP Period';
nPcount = DIMSIZ( cPer );

vC = 'GBP;1~USD;0.79~NZD;0.47~Reporting;1~';

WHILE( SCAN( '~', vC ) > 1 );
   nS = SCAN( '~', vC );
   vRec = SUBST( vC, 1, nS - 1 ) | ';';
   vC = SUBST( vC, nS + 1, LONG( vC ) - nS );

   nS = SCAN(';',vRec); vCur = SUBST(vRec,1,nS-1); vRec = SUBST(vRec,nS+1,LONG(vRec)-nS);
   nS = SCAN(';',vRec); nRate = NUMBR(SUBST(vRec,1,nS-1));

   nP = 1;
   WHILE( nP <= nPcount );
      vPer = DIMNM( cPer, nP );
      IF( DTYPE( cPer, vPer ) @= 'N' );
         vVl = 'Budget|Working|';
         WHILE( SCAN( '|', vVl ) > 1 );
            nS = SCAN( '|', vVl );
            vVer = SUBST( vVl, 1, nS - 1 );
            vVl = SUBST( vVl, nS + 1, LONG( vVl ) - nS );
            CellPutN( nRate, cCube, vPer, vVer, vCur, 'Average', 'Rate' );
            CellPutN( nRate, cCube, vPer, vVer, vCur, 'Closing', 'Rate' );
         END;
      ENDIF;
      nP = nP + 1;
   END;
END;

