process::WFP Create Default Subsets.PrologProcedure:
#Region Default subset on every WFP model dimension (rev D)
vList = 'WFP Cost Centre~WFP Currency~WFP Entity~WFP FX Rate Type~WFP FX Rates Measure~WFP Grade~WFP Headcount Measure~WFP Job Family~WFP Jurisdiction~WFP Location~WFP Pay Component~WFP Pay Rates Measure~WFP Period~WFP Position~WFP Tax Band~WFP Tax Bands Measure~WFP Tax Type~WFP Version~WFP Workforce Cost Measure~WFP Workforce Input Measure~';

WHILE( SCAN( '~', vList ) > 1 );
   nS = SCAN( '~', vList );
   vDim = SUBST( vList, 1, nS - 1 );
   vList = SUBST( vList, nS + 1, LONG( vList ) - nS );

   IF( SubsetExists( vDim, 'Default' ) = 0 );
      SubsetCreate( vDim, 'Default' );
   ELSE;
      SubsetDeleteAllElements( vDim, 'Default' );
   ENDIF;

   nE = 1;
   nEcount = DIMSIZ( vDim );
   WHILE( nE <= nEcount );
      SubsetElementInsert( vDim, 'Default', DIMNM( vDim, nE ), nE );
      nE = nE + 1;
   END;
END;

rules::WFP Headcount.rules:
SKIPCHECK;

# WFP Headcount dims: Period, Version, Entity, Cost Centre, Position, Measure
['_End Idx'] = N:
  IF( ATTRS('WFP Position', !WFP Position, 'End Period') @= '', 999,
      ATTRN('WFP Period', ATTRS('WFP Position', !WFP Position, 'End Period'), 'Period Index') );

['_Active'] = N:
  IF( !WFP Entity @= ATTRS('WFP Position', !WFP Position, 'Home Entity')
      & !WFP Cost Centre @= ATTRS('WFP Position', !WFP Position, 'Cost Centre')
      & ATTRN('WFP Period', !WFP Period, 'Period Index')
          >= ATTRN('WFP Period', ATTRS('WFP Position', !WFP Position, 'Start Period'), 'Period Index')
      & ATTRN('WFP Period', !WFP Period, 'Period Index') <= ['_End Idx'],
      1, 0 );

['Headcount'] = N:
  ['_Active'] * IF( ATTRS('WFP Position', !WFP Position, 'Position Status') @= 'Filled', 1, 0 );

['FTE'] = N:
  ['_Active'] * ATTRN('WFP Position', !WFP Position, 'FTE');

['Open Positions'] = N:
  ['_Active'] * IF( ATTRS('WFP Position', !WFP Position, 'Position Status') @= 'Open Req', 1, 0 );

FEEDERS;

['Headcount'] => ['FTE'], ['Open Positions'];
